import NextAuth from "next-auth";
import Google from "next-auth/providers/google";
import Credentials from "next-auth/providers/credentials";

import { authConfig } from "@/lib/auth.config";
import { findOrCreateOAuthUser, verifyPassword } from "@/lib/users";

export const { handlers, auth, signIn, signOut } = NextAuth({
  ...authConfig,
  providers: [
    Google,
    Credentials({
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        const email =
          typeof credentials?.email === "string" ? credentials.email : "";
        const password =
          typeof credentials?.password === "string" ? credentials.password : "";
        if (!email || !password) return null;

        const user = await verifyPassword(email, password);
        return user ?? null;
      },
    }),
  ],
  callbacks: {
    ...authConfig.callbacks,
    async signIn({ user, account }) {
      // Credentials sign-ins are already validated by `authorize` above.
      // Google sign-ins need to be linked to (or create) a user record.
      if (account?.provider === "google") {
        if (!user.email) return false;
        await findOrCreateOAuthUser({
          email: user.email,
          name: user.name ?? user.email,
        });
      }
      return true;
    },
    async jwt({ token, user, account }) {
      if (user && account?.provider === "google" && user.email) {
        const dbUser = await findOrCreateOAuthUser({
          email: user.email,
          name: user.name ?? user.email,
        });
        token.id = dbUser.id;
      } else if (user) {
        // Credentials provider returns our own User (with our own id).
        token.id = (user as { id: string }).id;
      }
      return token;
    },
  },
});

